"use client";

import productsData from "@/lib/productsData";
import { AnimatePresence, motion } from "framer-motion";
import { Banknote, CheckCircle2, ChevronRight, CreditCard, MapPin, Package, Sparkles, Truck, User } from "lucide-react";
import Image from "next/image";
import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { Suspense, useCallback, useEffect, useRef, useState } from "react";

interface Product { _id: string; name: string; price: number; images: string[]; }
interface FullCartItem {
  _id: string;
  productId?: string;
  name: string;
  price: number;
  quantity: number;
  image?: string;
  size?: string | null;
  color?: string | null;
}
interface FormData {
  email: string; newsletter: boolean; country: string;
  firstName: string; lastName: string; address: string;
  apartment: string; city: string; postalCode: string;
  phone: string; shippingMethod: string;
}

const SHIPPING_COST_CAIRO = 75;

function GlassSection({ icon, title, children }: { icon: React.ReactNode; title: string; children: React.ReactNode }) {
  return (
    <fieldset
      className="relative overflow-hidden rounded-2xl p-5 sm:p-6"
      style={{
        background: "linear-gradient(135deg, rgba(255,248,236,0.08) 0%, rgba(255,248,236,0.025) 100%)",
        backdropFilter: "blur(24px) saturate(160%)",
        WebkitBackdropFilter: "blur(24px) saturate(160%)",
        border: "1px solid rgba(255,248,236,0.09)",
        boxShadow: "0 16px 48px rgba(0,0,0,0.3), inset 0 1px 0 rgba(255,248,236,0.14)",
        margin: 0,
        minWidth: 0,
      }}
    >
      <div className="absolute inset-x-5 top-0 h-px pointer-events-none"
           style={{ background: "linear-gradient(90deg, transparent, rgba(255,248,236,0.18), transparent)" }} />
      <legend style={{ padding: 0, margin: 0, display: "contents" }}>
        <span className="flex items-center gap-3 mb-5 sm:mb-6">
          <span className="p-2 rounded-xl"
                style={{
                  background: "linear-gradient(135deg, rgba(168,121,53,0.14), rgba(168,121,53,0.04))",
                  border: "1px solid rgba(168,121,53,0.2)",
                }}>
            <span style={{ color: "#A87935", display: "inline-flex" }}>{icon}</span>
          </span>
          <span
            className="font-light text-white text-lg sm:text-xl"
            style={{ fontFamily: "'Cormorant Garamond', serif", letterSpacing: "0.08em" }}
          >
            {title}
          </span>
        </span>
      </legend>
      {children}
    </fieldset>
  );
}

function CheckoutContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [cart, setCart] = useState<FullCartItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [success, setSuccess] = useState("");
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [fromCart, setFromCart] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<"cod" | "card">("cod");
  const [form, setForm] = useState<FormData>({
    email: "", newsletter: false, country: "Egypt",
    firstName: "", lastName: "", address: "", apartment: "",
    city: "", postalCode: "", phone: "", shippingMethod: "within_egypt",
  });
  const cancelOnLeaveReadyRef = useRef(false);
  const paymentRedirectInProgressRef = useRef(false);
  const errorRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (error) {
      const t = window.setTimeout(() => errorRef.current?.focus({ preventScroll: false }), 60);
      return () => window.clearTimeout(t);
    }
  }, [error]);
  const canceledParam = searchParams.get("canceled");
  const canceledOrderId = searchParams.get("orderId");

  const cancelCheckoutSession = useCallback(async (keepalive = false, orderId?: string | null) => {
    if (typeof window !== "undefined") {
      orderId = orderId || sessionStorage.getItem("checkoutOrderId");
      sessionStorage.removeItem("checkoutItems");
      sessionStorage.removeItem("selectedOrder");
      sessionStorage.removeItem("checkoutOrderId");
    }

    try {
      await fetch("/api/checkout/cancel", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ orderId: orderId || undefined }),
        keepalive,
      });
    } catch {
      // Leaving the page should never block navigation.
    }
  }, []);

  useEffect(() => {
    if (canceledParam === "1") {
      setError("Checkout was canceled. Your cart is still here.");
      void cancelCheckoutSession(false, canceledOrderId);
    }
  }, [canceledParam, canceledOrderId, cancelCheckoutSession]);

  useEffect(() => {
    (async () => {
      setLoading(true);
      try {
        const checkoutJson = typeof window !== "undefined" ? sessionStorage.getItem("checkoutItems") : null;
        if (checkoutJson) {
          const items = JSON.parse(checkoutJson);
          const merged = items.map((i: any) => ({
            _id: i._id||i.productId,
            productId: i.productId||i._id,
            name: i.name??"Unknown",
            price: Number(i.price??0),
            quantity: i.quantity??1,
            image: i.image||"/images/placeholder.svg",
            size: i.size ?? null,
            color: i.color ?? null,
          }));
          if (merged.length > 0) { setCart(merged); setLoading(false); return; }
        }

        setFromCart(true);
        const res = await fetch("/api/cart", { cache: "no-store" });
        if (!res.ok) {
          throw new Error(`Cart request failed with status ${res.status}`);
        }

        const cartData = await res.json();
        const items = cartData.items||[];
        
        if (!Array.isArray(items)||items.length===0) { 
          setError("Your cart is empty."); 
          setCart([]); 
          setLoading(false); 
          return; 
        }

        setCart(items.map((i: any) => {
          const p = productsData.find((p: Product) => String(p._id) === String(i.productId));
          return {
            _id: i.productId,
            productId: i.productId,
            name: i.name??p?.name??"Unknown",
            price: Number(i.price??p?.price??0),
            quantity: i.quantity??1,
            image: i.image??p?.images?.[0]??"/images/placeholder.svg",
            size: i.size ?? null,
            color: i.color ?? null,
          };
        }));
      } catch (err) { 
        console.error("Failed to load checkout:", err);
        setError("Failed to load checkout data."); 
      }
      finally { setLoading(false); }
    })();
  }, []);

  useEffect(() => {
    const cancelOnPageLeave = () => {
      if (!cancelOnLeaveReadyRef.current) return;
      if (paymentRedirectInProgressRef.current) return;
      void cancelCheckoutSession(true);
    };
    const readyTimer = window.setTimeout(() => {
      cancelOnLeaveReadyRef.current = true;
    }, 0);

    window.addEventListener("pagehide", cancelOnPageLeave);
    return () => {
      window.clearTimeout(readyTimer);
      window.removeEventListener("pagehide", cancelOnPageLeave);
      cancelOnPageLeave();
    };
  }, [cancelCheckoutSession]);

  const subtotal = cart.reduce((s, i) => s + i.price * i.quantity, 0);
  const shippingCost = form.shippingMethod === "within_egypt" ? SHIPPING_COST_CAIRO : 0;
  const [couponInput, setCouponInput] = useState("");
  const [coupon, setCoupon] = useState<{ code: string; discount: number } | null>(null);
  const [couponError, setCouponError] = useState("");
  const [couponBusy, setCouponBusy] = useState(false);
  const [loyaltyBalance, setLoyaltyBalance] = useState(0);
  const [loyaltyUse, setLoyaltyUse] = useState(0);
  const [giftWrap, setGiftWrap] = useState(false);
  const [giftMessage, setGiftMessage] = useState("");
  const [cardAvailable, setCardAvailable] = useState(true);
  const GIFT_WRAP_FEE = 50;  const giftFee = giftWrap ? GIFT_WRAP_FEE : 0;
  const loyaltyDiscount = Math.min(Math.floor(Math.max(0, loyaltyUse) / 100) * 10, Math.max(0, subtotal - (coupon?.discount ?? 0)));
  const total = Math.max(0, subtotal - (coupon?.discount ?? 0) - loyaltyDiscount + shippingCost + giftFee);

  async function applyCoupon() {
    const code = couponInput.trim();
    if (!code || couponBusy) return;
    setCouponBusy(true);
    setCouponError("");
    try {
      const res = await fetch("/api/coupons", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code, subtotal }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(data.error || "Invalid coupon");
      setCoupon({ code: data.coupon.code, discount: Number(data.coupon.discount ?? 0) });
    } catch (e) {
      setCoupon(null);
      setCouponError(e instanceof Error ? e.message : "Invalid coupon");
    } finally {
      setCouponBusy(false);
    }
  }

  useEffect(() => {
    fetch("/api/loyalty", { cache: "no-store" })
      .then((r) => r.json())
      .then((d) => setLoyaltyBalance(Number(d.points ?? 0)))
      .catch(() => undefined);
    fetch("/api/checkout/status", { cache: "no-store" })
      .then((r) => r.json())
      .then((d) => {
        if (d && d.stripe === false) {
          setCardAvailable(false);
          setPaymentMethod("cod");
        }
      })
      .catch(() => undefined);
  }, []);

  const update = (k: keyof FormData, v: any) => setForm((f) => ({ ...f, [k]: v }));

  async function handleCancel() {
    setError("");
    setSuccess("");
    await cancelCheckoutSession();
    router.push("/cart");
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(""); 
    setSuccess(""); 
    setSubmitting(true);

    if (!cart.length) { 
      setError("No products to order."); 
      setSubmitting(false); 
      return; 
    }

    const required: [keyof FormData, string][] = [
      ["email","email"],
      ["firstName","first name"],
      ["lastName","last name"],
      ["address","address"],
      ["city","city"],
      ["phone","phone"]
    ];
    for (const [k, label] of required) { 
      if (!form[k]) { 
        setError(`Please enter your ${label}.`); 
        setSubmitting(false); 
        return; 
      } 
    }

    const items = cart
      .filter(item => item.productId && (item.quantity ?? 0) > 0)
      .map((item) => ({
        productId: item.productId || item._id,
        name: item.name,
        price: item.price,
        quantity: item.quantity,
        size: item.size || "One Size",
        color: item.color || "Default",
        image: item.image || "/images/placeholder.svg",
      }));

    if (!items.length) { 
      setError("No valid items in cart."); 
      setSubmitting(false); 
      return; 
    }

    console.log("📤 Sending order payload:", {
      items,
      total,
      customerInfo: {
        email: form.email,
        name: `${form.firstName} ${form.lastName}`,
        address: form.address,
        city: form.city,
        phone: form.phone,
      }
    });

    try {
      const { trackEvent } = await import("@/lib/analytics").catch(() => ({ trackEvent: () => undefined as void }));
      trackEvent("begin_checkout", { value: Number(total ?? 0) });
      if (paymentMethod === "card") {
        const origin = typeof window !== "undefined" ? window.location.origin : "";
        const res = await fetch("/api/checkout", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            items: items.map((item) => ({
              productId: item.productId,
              quantity: item.quantity,
              size: item.size,
              color: item.color,
            })),
            customerInfo: {
              email: form.email,
              firstName: form.firstName,
              lastName: form.lastName,
              name: `${form.firstName} ${form.lastName}`,
              address: form.address,
              apartment: form.apartment || undefined,
              city: form.city,
              postalCode: form.postalCode || undefined,
              country: form.country,
              phone: form.phone,
              newsletter: form.newsletter,
              shippingMethod: form.shippingMethod,
              shippingCost,
            },
            successUrl: `${origin}/checkout/confirmation?paymentStatus=paid&session_id={CHECKOUT_SESSION_ID}`,
            cancelUrl: `${origin}/checkout?canceled=1`,
          }),
        });
        const data = await res.json().catch(() => ({}));
        if (!res.ok || !data?.url) {
          throw new Error(data?.error || "Card payment is not available right now.");
        }
        if (typeof data?.orderId === "string" && data.orderId) {
          sessionStorage.setItem("checkoutOrderId", data.orderId);
        }
        paymentRedirectInProgressRef.current = true;
        window.location.href = data.url;
        return;
      }

      const res = await fetch("/api/saveorder", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          items,
          total,
          customerInfo: {
            email: form.email,
            firstName: form.firstName,
            lastName: form.lastName,
            name: `${form.firstName} ${form.lastName}`,
            address: form.address,
            apartment: form.apartment || undefined,
            city: form.city,
            postalCode: form.postalCode || undefined,
            country: form.country,
            phone: form.phone,
            newsletter: form.newsletter,
            shippingMethod: form.shippingMethod,
            shippingCost,
          },
          paymentMethod,
          ...(coupon ? { couponCode: coupon.code } : {}),
          ...(loyaltyDiscount > 0 ? { loyaltyPoints: Math.floor(loyaltyDiscount / 10) * 100 } : {}),
          ...(giftWrap ? { giftWrap: true, giftMessage: giftMessage.trim() || undefined } : {}),
        }),
      });

      const data = await res.json();
      console.log("📥 Server response:", data);

      if (!res.ok) { 
        throw new Error(data?.error || "Failed to place order"); 
      }

      setSuccess("Order placed successfully."); 
      setCart([]);
      
      if (typeof window !== "undefined") { 
        sessionStorage.removeItem("checkoutItems"); 
        sessionStorage.removeItem("selectedOrder"); 
      }
      sessionStorage.removeItem("checkoutOrderId");
      
      if (fromCart) {
        await fetch("/api/cart", { method: "DELETE" });
        window.dispatchEvent(new Event("cart:changed"));
      }

      const placedOrderId = typeof data?.orderId === "string" ? data.orderId : "";

      try {
        const { trackEvent } = await import("@/lib/analytics").catch(() => ({ trackEvent: () => undefined as void }));
        trackEvent("purchase", { value: Number(data?.total ?? total ?? 0) });
      } catch {
        // ignore analytics errors
      }
      router.push(
        placedOrderId
          ? `/checkout/confirmation?orderId=${encodeURIComponent(placedOrderId)}&paymentStatus=${encodeURIComponent(data?.paymentStatus || "pending")}`
          : "/checkout/confirmation?paymentStatus=pending"
      );
    } catch (err: any) { 
      console.error("❌ Order error:", err);
      setError(err.message || "Failed to place order."); 
    }
    finally { 
      setSubmitting(false); 
    }
  }

  if (loading) return (
    <div className="min-h-screen bg-[#F5F1E8] flex items-center justify-center">
      <motion.p animate={{ opacity:[0.3,0.7,0.3] }} transition={{ repeat:Infinity, duration:1.8 }}
        className="text-white/30 text-[10px] tracking-[0.4em] uppercase"
        style={{ fontFamily:"'Jost', sans-serif" }}>
        Loading Checkout…
      </motion.p>
    </div>
  );

  if (success) return (
    <div className="min-h-screen bg-[#F5F1E8] flex items-center justify-center px-4 sm:px-6">
      <motion.div
        initial={{ opacity:0, scale:0.95, y:20 }}
        animate={{ opacity:1, scale:1, y:0 }}
        transition={{ duration:0.8, ease:[0.22,1,0.36,1] }}
        className="text-center max-w-sm"
        style={{ fontFamily:"'Jost', sans-serif" }}
      >
        <div className="flex justify-center mb-6">
          <div className="w-16 h-16 rounded-3xl flex items-center justify-center"
               style={{ background:"linear-gradient(135deg, rgba(168,121,53,0.2), rgba(168,121,53,0.06))", border:"1px solid rgba(168,121,53,0.3)" }}>
            <CheckCircle2 strokeWidth={1.2} className="w-8 h-8" style={{ color:"#A87935" }} />
          </div>
        </div>
        <h2 className="font-light text-white mb-3" style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:"clamp(1.8rem, 5vw, 2rem)", letterSpacing:"0.06em" }}>
          Order <em style={{ color:"#A87935" }}>Confirmed</em>
        </h2>
        <p className="text-white/35 text-sm font-light tracking-widest">Redirecting to your orders…</p>
      </motion.div>
    </div>
  );

  return (
    <>
      <style>{`
        body { background: #F5F1E8; }
        ::selection { background: #A87935; color: #F5F1E8; }
        select option { background: #1A1512; color: rgba(255,248,236,0.8); }

        input[type="checkbox"] {
          accent-color: #A87935;
          width: 14px !important; height: 14px !important;
          border-radius: 4px !important;
          padding: 0 !important;
          cursor: pointer;
        }
        input[type="radio"] {
          accent-color: #A87935;
          width: 14px !important; height: 14px !important;
          padding: 0 !important;
          cursor: pointer;
        }
        
        @media (max-width: 640px) {
          input[type="text"], input[type="email"], input[type="tel"], select, textarea {
            font-size: 16px !important;
          }
        }
      `}</style>

      <div className="relative min-h-screen bg-[#F5F1E8] text-white" style={{ fontFamily:"'Jost', sans-serif" }}>

        <div className="relative z-10 max-w-5xl mx-auto px-4 sm:px-6 md:px-10 pt-20 sm:pt-28 pb-24 sm:pb-32">

          {/* ── HEADER ── */}
          <motion.div initial={{ opacity:0, y:20 }} animate={{ opacity:1, y:0 }} transition={{ duration:0.8 }} className="mb-8 sm:mb-12">
            <p className="text-white/20 text-[8px] sm:text-[9px] tracking-[0.45em] uppercase mb-3 sm:mb-4">Final Step</p>
            <h1 className="font-light text-white leading-none mb-2"
                style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:"clamp(2rem, 7vw, 4.5rem)", letterSpacing:"0.04em" }}>
              Check<em style={{ color:"#A87935", fontStyle:"italic" }}>out</em>
            </h1>
            <div className="mt-4 sm:mt-5 h-px" style={{ background:"linear-gradient(90deg, rgba(168,121,53,0.4), transparent)" }} />
          </motion.div>

          {/* ── ERROR ── */}
          <AnimatePresence>
            {error && (
              <motion.div initial={{ opacity:0, y:-8 }} animate={{ opacity:1, y:0 }} exit={{ opacity:0 }}
                ref={errorRef}
                tabIndex={-1}
                role="alert"
                aria-live="assertive"
                className="mb-6 px-4 sm:px-5 py-3 sm:py-3.5 rounded-2xl flex items-center gap-3 outline-none"
                style={{ background:"rgba(255,60,60,0.08)", border:"1px solid rgba(255,80,80,0.2)", backdropFilter:"blur(16px)" }}>
                <span className="text-red-400/70 text-xs tracking-[0.2em] font-light">{error}</span>
              </motion.div>
            )}
          </AnimatePresence>

          {cart.length > 0 ? (
            <div className="grid grid-cols-1 lg:grid-cols-[1fr_360px] gap-6 items-start">

              {/* ── LEFT — form ── */}
              <form onSubmit={handleSubmit} className="flex flex-col gap-4 sm:gap-5">

                {/* Contact */}
                <motion.div initial={{ opacity:0, y:20 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.1, duration:0.7 }}>
                  <GlassSection icon={<User strokeWidth={1.3} className="w-4 h-4" />} title="Contact">
                    <div className="flex flex-col gap-3 max-w-lg">
                      <p className="text-white/25 text-[9px] sm:text-[10px] tracking-[0.25em] font-light">
                        Have an account?{" "}
                        <Link href="/login" className="text-[#A87935] hover:underline transition-colors">Sign in</Link>
                      </p>
                      <input type="email" name="email" aria-label="Email address" spellCheck={false} placeholder="Email address…" value={form.email} onChange={(e) => update("email", e.target.value)} autoComplete="email" required />
                      <label className="flex items-center gap-3 cursor-pointer group">
                        <input type="checkbox" checked={form.newsletter} onChange={(e) => update("newsletter", e.target.checked)} />
                        <span className="text-white/30 text-[9px] sm:text-[10px] tracking-[0.22em] uppercase group-hover:text-white/50 transition-colors">
                          Email me with news and offers
                        </span>
                      </label>
                    </div>
                  </GlassSection>
                </motion.div>

                {/* Delivery */}
                <motion.div initial={{ opacity:0, y:20 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.18, duration:0.7 }}>
                  <GlassSection icon={<MapPin strokeWidth={1.3} className="w-4 h-4" />} title="Delivery">
                    <div className="grid gap-3 max-w-lg">
                      <select
                        value={form.country}
                        onChange={(e) => update("country", e.target.value)}
                        className="luxury-select"
                        required
                      >
                        <option value="Egypt">Egypt</option>
                      </select>
                      <div className="grid grid-cols-1 gap-3 min-[420px]:grid-cols-2">
                        <input type="text" name="firstName" aria-label="First name" value={form.firstName} onChange={(e) => update("firstName", e.target.value)} autoComplete="given-name" required />
                        <input type="text" name="lastName" aria-label="Last name" value={form.lastName} onChange={(e) => update("lastName", e.target.value)} autoComplete="family-name" required />
                      </div>
                      <input type="text" name="address" aria-label="Street address" value={form.address} onChange={(e) => update("address", e.target.value)} autoComplete="street-address" required />
                      <input type="text" name="apartment" aria-label="Apartment (optional)" value={form.apartment} onChange={(e) => update("apartment", e.target.value)} />
                      <div className="grid grid-cols-1 gap-3 min-[420px]:grid-cols-2">
                        <input type="text" name="city" aria-label="City" value={form.city} onChange={(e) => update("city", e.target.value)} autoComplete="address-level2" required />
                        <input type="text" name="postalCode" aria-label="Postal code (optional)" value={form.postalCode} onChange={(e) => update("postalCode", e.target.value)} />
                      </div>
                      <input type="tel" name="phone" aria-label="Phone number" value={form.phone} onChange={(e) => update("phone", e.target.value)} autoComplete="tel" required />
                    </div>
                  </GlassSection>
                </motion.div>

                {/* Shipping */}
                <motion.div initial={{ opacity:0, y:20 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.26, duration:0.7 }}>
                  <GlassSection icon={<Truck strokeWidth={1.3} className="w-4 h-4" />} title="Shipping Method">
                    <div className="max-w-lg">
                      <label
                        className="flex items-center justify-between p-4 rounded-xl cursor-pointer transition-colors duration-300 min-h-[56px]"
                        style={form.shippingMethod === "within_egypt" ? {
                          background:"linear-gradient(135deg, rgba(168,121,53,0.12), rgba(168,121,53,0.04))",
                          border:"1px solid rgba(168,121,53,0.3)",
                        } : {
                          background:"rgba(255,248,236,0.03)",
                          border:"1px solid rgba(255,248,236,0.08)",
                        }}
                      >
                        <div className="flex items-center gap-3">
                          <input type="radio" name="shipping" value="within_egypt"
                            checked={form.shippingMethod === "within_egypt"}
                            onChange={() => update("shippingMethod", "within_egypt")} />
                          <div>
                            <p className="text-white/70 text-sm font-light tracking-wide">Within egypt</p>
                            <p className="text-white/30 text-[9px] tracking-[0.25em] uppercase mt-0.5">Standard Delivery · 2–3 days</p>
                          </div>
                        </div>
                        <span className="font-light whitespace-nowrap ml-2" style={{ color:"#A87935", fontFamily:"'Cormorant Garamond', serif", fontSize:"1.1rem" }}>
                          EGP 75
                        </span>
                      </label>
                    </div>
                  </GlassSection>
                </motion.div>

                {/* Offers & Gifting */}
                <motion.div initial={{ opacity:0, y:20 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.28, duration:0.7 }}>
                  <GlassSection icon={<Sparkles strokeWidth={1.3} className="w-4 h-4" />} title="Offers & Gifting">
                    <div className="flex max-w-lg flex-col gap-4">
                      <div>
                        <div className="flex gap-2">
                          <input
                            type="text"
                            placeholder="Coupon code"
                            value={couponInput}
                            onChange={(e) => setCouponInput(e.target.value.toUpperCase())}
                            aria-label="Coupon code"
                            className="min-w-0 flex-1"
                          />
                          <button
                            type="button"
                            onClick={applyCoupon}
                            disabled={couponBusy || !couponInput.trim()}
                            className="shrink-0 rounded-full px-5 text-[10px] uppercase tracking-[0.25em] text-[#A87935] transition-colors disabled:opacity-50 min-h-[44px]"
                            style={{ border: "1px solid rgba(168,121,53,0.35)" }}
                          >
                            {couponBusy ? "Checking…" : "Apply"}
                          </button>
                        </div>
                        {coupon && (
                          <p className="mt-2 text-xs tracking-wide text-[#A87935]">
                            {coupon.code} applied — EGP {coupon.discount.toLocaleString()} off.
                            <button type="button" onClick={() => { setCoupon(null); setCouponInput(""); }} className="ml-2 underline">Remove</button>
                          </p>
                        )}
                        {couponError && <p className="mt-2 text-xs text-red-400/80" role="alert">{couponError}</p>}
                      </div>
                      {loyaltyBalance >= 100 && (
                        <div>
                          <label className="text-white/30 text-[9px] sm:text-[10px] tracking-[0.22em] uppercase" htmlFor="loyalty-use">
                            Loyalty points (balance {loyaltyBalance} · 100 pts = EGP 10)
                          </label>
                          <input
                            id="loyalty-use"
                            type="number"
                            min={0}
                            max={loyaltyBalance}
                            step={100}
                            value={loyaltyUse || ""}
                            onChange={(e) => setLoyaltyUse(Math.max(0, Math.floor(Number(e.target.value) || 0)))}
                            placeholder="Points to redeem"
                            className="mt-2 max-w-[220px]"
                          />
                        </div>
                      )}
                      <label className="flex cursor-pointer items-center gap-3">
                        <input type="checkbox" checked={giftWrap} onChange={(e) => setGiftWrap(e.target.checked)} />
                        <span className="text-white/30 text-[9px] sm:text-[10px] tracking-[0.22em] uppercase">
                          Gift wrap · EGP {GIFT_WRAP_FEE}
                        </span>
                      </label>
                      {giftWrap && (
                        <textarea
                          value={giftMessage}
                          onChange={(e) => setGiftMessage(e.target.value.slice(0, 500))}
                          placeholder="Gift message (optional)"
                          rows={2}
                          aria-label="Gift message"
                        />
                      )}
                    </div>
                  </GlassSection>
                </motion.div>

                {/* Payment */}
                <motion.div initial={{ opacity:0, y:20 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.3, duration:0.7 }}>
                  <GlassSection icon={<CreditCard strokeWidth={1.3} className="w-4 h-4" />} title="Payment Method">
                    <div className="grid gap-3">
                      {[
                        {
                          value: "cod" as const,
                          title: "Cash on delivery",
                          detail: "Order is created with pending payment status.",
                          icon: Banknote,
                          disabled: false,
                        },
                        {
                          value: "card" as const,
                          title: "Card payment",
                          detail: cardAvailable
                            ? "Secure card checkout."
                            : "Card payments are not available right now — cash on delivery works.",
                          icon: CreditCard,
                          disabled: !cardAvailable,
                        },
                      ].map((option) => {
                        const Icon = option.icon;
                        const active = paymentMethod === option.value;
                        return (
                          <button
                            type="button"
                            key={option.value}
                            onClick={() => setPaymentMethod(option.value)}
                            disabled={option.disabled}
                            className="flex min-h-[64px] items-center justify-between gap-4 rounded-xl p-4 text-left transition-colors disabled:cursor-not-allowed disabled:opacity-45"
                            style={active ? {
                              background:"linear-gradient(135deg, rgba(168,121,53,0.12), rgba(168,121,53,0.04))",
                              border:"1px solid rgba(168,121,53,0.3)",
                            } : {
                              background:"rgba(255,248,236,0.03)",
                              border:"1px solid rgba(255,248,236,0.08)",
                            }}
                            aria-pressed={active}
                          >
                            <span className="flex items-center gap-3">
                              <span className="flex h-10 w-10 items-center justify-center rounded-full border border-white/10 bg-white/[0.04] text-[#A87935]">
                                <Icon className="h-4 w-4" strokeWidth={1.35} />
                              </span>
                              <span>
                                <span className="block text-sm tracking-[0.06em] text-white/76">{option.title}</span>
                                <span className="mt-1 block text-[10px] uppercase tracking-[0.18em] text-white/32">{option.detail}</span>
                              </span>
                            </span>
                            <span className={`h-3 w-3 rounded-full ${active ? "bg-[#A87935]" : "bg-white/18"}`} />
                          </button>
                        );
                      })}
                    </div>
                  </GlassSection>
                </motion.div>

                {/* Submit / Cancel */}
                <motion.div initial={{ opacity:0, y:20 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.34, duration:0.7 }}>
                  <div className="flex flex-col gap-3">
                    <motion.button
                      type="submit"
                      disabled={submitting}
                      whileHover={{ scale:1.015 }}
                      whileTap={{ scale:0.985 }}
                      className="relative w-full overflow-hidden rounded-full py-4 flex items-center justify-center gap-3 disabled:opacity-50 min-h-[48px]"
                      style={{
                        background:"linear-gradient(135deg, rgba(168,121,53,0.22), rgba(178,149,78,0.10))",
                        border:"1px solid rgba(168,121,53,0.35)",
                        backdropFilter:"blur(16px)",
                        boxShadow:"0 0 28px rgba(168,121,53,0.12), inset 0 1px 0 rgba(255,248,236,0.14)",
                      }}
                    >
                      <span className="text-[#A87935] text-[10px] tracking-[0.32em] uppercase font-light">
                        {submitting ? "Placing Order…" : "Place Order"}
                      </span>
                      {!submitting && <ChevronRight strokeWidth={1.3} className="w-4 h-4 text-[#A87935]" />}
                    </motion.button>
                    <button
                      type="button"
                      onClick={handleCancel}
                      className="w-full rounded-full py-4 text-[10px] tracking-[0.28em] uppercase font-light border border-white/10 text-white/60 hover:text-white hover:border-white/30 transition-colors min-h-[48px]"
                    >
                      Cancel Checkout
                    </button>
                  </div>
                </motion.div>
              </form>

              {/* ── RIGHT — Order summary ── */}
              <motion.div initial={{ opacity:0, y:20 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.2, duration:0.8 }}
                className="sticky top-20 sm:top-24 flex flex-col gap-4">

                {/* Summary card */}
                <div className="relative overflow-hidden rounded-2xl p-5"
                     style={{ background:"linear-gradient(135deg, rgba(255,248,236,0.08) 0%, rgba(255,248,236,0.025) 100%)", backdropFilter:"blur(24px) saturate(160%)", WebkitBackdropFilter:"blur(24px) saturate(160%)", border:"1px solid rgba(255,248,236,0.09)", boxShadow:"0 16px 48px rgba(0,0,0,0.3), inset 0 1px 0 rgba(255,248,236,0.14)" }}>
                  <div className="absolute inset-x-4 top-0 h-px pointer-events-none"
                       style={{ background:"linear-gradient(90deg, transparent, rgba(255,248,236,0.16), transparent)" }} />

                  <p className="text-white/20 text-[8px] sm:text-[9px] tracking-[0.4em] uppercase mb-4">Your Order</p>
                  <h3 className="font-light text-white mb-5" style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:"clamp(1.2rem, 3vw, 1.4rem)", letterSpacing:"0.07em" }}>
                    Order <em style={{ color:"#A87935" }}>Summary</em>
                  </h3>

                  {/* Items */}
                  <div className="flex flex-col gap-3 mb-5">
                    {cart.map((item, i) => (
                      <div key={`${item._id}-${item.size || "nosize"}-${item.color || "nocolor"}-${i}`} className="flex items-center gap-3">
                        <div className="relative w-14 h-14 flex-shrink-0 overflow-hidden rounded-xl"
                             style={{ boxShadow:"0 4px 16px rgba(0,0,0,0.4)" }}>
                          <Image src={item.image||"/images/placeholder.svg"} alt={item.name} fill className="object-cover" sizes="56px" />
                          <div className="absolute -top-1 -right-1 w-4 h-4 rounded-full flex items-center justify-center text-[9px] font-light"
                               style={{ background:"rgba(168,121,53,0.9)", color:"#F5F1E8" }}>
                            {item.quantity}
                          </div>
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-white/60 text-xs font-light truncate"
                             style={{ fontFamily:"'Cormorant Garamond', serif", letterSpacing:"0.05em" }}>
                            {item.name}
                          </p>
                          {(item.size || item.color) && (
                            <p className="text-white/30 text-[9px] tracking-[0.25em] uppercase mt-0.5">
                              {item.size && <>Size {item.size}</>}
                              {item.color && <> · Color {item.color}</>}
                            </p>
                          )}
                        </div>
                        <p className="text-white/45 text-xs font-light shrink-0">
                          EGP {(item.price * item.quantity).toLocaleString()}
                        </p>
                      </div>
                    ))}
                  </div>

                  <div className="h-px mb-4" style={{ background:"rgba(255,248,236,0.06)" }} />

                  <div className="flex flex-col gap-2 mb-4">
                    <div className="flex justify-between">
                      <p className="text-white/30 text-[9px] tracking-[0.3em] uppercase">Subtotal</p>
                      <p className="text-white/50 text-xs">EGP {subtotal.toLocaleString()}</p>
                    </div>
                    {coupon && (
                      <div className="flex justify-between">
                        <p className="text-white/30 text-[9px] tracking-[0.3em] uppercase">Coupon {coupon.code}</p>
                        <p className="text-xs" style={{ color: "#A87935" }}>− EGP {coupon.discount.toLocaleString()}</p>
                      </div>
                    )}
                    {loyaltyDiscount > 0 && (
                      <div className="flex justify-between">
                        <p className="text-white/30 text-[9px] tracking-[0.3em] uppercase">Loyalty</p>
                        <p className="text-xs" style={{ color: "#A87935" }}>− EGP {loyaltyDiscount.toLocaleString()}</p>
                      </div>
                    )}
                    <div className="flex justify-between">
                      <p className="text-white/30 text-[9px] tracking-[0.3em] uppercase">Shipping</p>
                      <p className="text-white/50 text-xs">EGP {shippingCost.toLocaleString()}</p>
                    </div>
                    {giftWrap && (
                      <div className="flex justify-between">
                        <p className="text-white/30 text-[9px] tracking-[0.3em] uppercase">Gift Wrap</p>
                        <p className="text-white/50 text-xs">EGP {GIFT_WRAP_FEE.toLocaleString()}</p>
                      </div>
                    )}
                  </div>

                  <div className="rounded-xl px-4 py-3.5 flex justify-between items-center"
                       style={{ background:"linear-gradient(135deg, rgba(168,121,53,0.14), rgba(168,121,53,0.04))", border:"1px solid rgba(168,121,53,0.22)" }}>
                    <p className="text-[#A87935] text-[9px] tracking-[0.35em] uppercase">Total</p>
                    <p className="font-light" style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:"clamp(1.1rem, 3vw, 1.3rem)", color:"#A87935", letterSpacing:"0.06em" }}>
                      EGP {total.toLocaleString()}
                    </p>
                  </div>
                </div>

                {/* Trust badges */}
                <div className="flex flex-col gap-2">
                  {[
                    { icon:<Package strokeWidth={1.2} className="w-3.5 h-3.5" />, text:"Secure checkout" },
                    { icon:<Truck strokeWidth={1.2} className="w-3.5 h-3.5" />, text:"Free returns on all orders" },
                    { icon:<CheckCircle2 strokeWidth={1.2} className="w-3.5 h-3.5" />, text:"Authentic pieces, guaranteed" },
                  ].map((b, i) => (
                    <div key={i} className="flex items-center gap-2.5">
                      <span className="text-white/20">{b.icon}</span>
                      <p className="text-white/20 text-[9px] tracking-[0.25em] uppercase">{b.text}</p>
                    </div>
                  ))}
                </div>
              </motion.div>
            </div>
          ) : (
            <motion.div initial={{ opacity:0, y:30 }} animate={{ opacity:1, y:0 }} transition={{ duration:0.8 }}
              className="flex flex-col items-center justify-center text-center py-20 sm:py-28">
              <div className="w-16 h-16 rounded-3xl flex items-center justify-center mb-6"
                   style={{ background:"linear-gradient(135deg, rgba(255,248,236,0.08), rgba(255,248,236,0.02))", border:"1px solid rgba(255,248,236,0.09)" }}>
                <Package strokeWidth={1} className="w-7 h-7 text-white/20" />
              </div>
              <h2 className="font-light text-white mb-3"
                  style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:"clamp(1.5rem, 5vw, 1.8rem)", letterSpacing:"0.06em" }}>
                Nothing to <em style={{ color:"#A87935" }}>checkout</em>
              </h2>
              <p className="text-white/25 text-sm font-light tracking-widest mb-8">Add items to your cart first.</p>
              <Link href="/shop"
                className="inline-flex items-center gap-3 px-8 py-3.5 rounded-full text-[#A87935] text-[10px] tracking-[0.3em] uppercase font-light transition-[transform,background-color] duration-500 hover:scale-[1.02] min-h-[44px]"
                style={{ background:"linear-gradient(135deg, rgba(168,121,53,0.14), rgba(168,121,53,0.04))", border:"1px solid rgba(168,121,53,0.25)", backdropFilter:"blur(16px)" }}>
                Continue Shopping
              </Link>
            </motion.div>
          )}
        </div>
      </div>
    </>
  );
}

export default function CheckoutPage() {
  return (
    <Suspense
      fallback={
        <div className="flex min-h-screen items-center justify-center bg-[#F5F1E8]">
          <p className="text-[10px] uppercase tracking-[0.32em] text-[#A87935]">Loading checkout</p>
        </div>
      }
    >
      <CheckoutContent />
    </Suspense>
  );
}
